const TARO_BUILTIN_NAMES = new Set(['View', 'Text', 'Image']);

// ---------------------------------------------------------------------------
// Theme & Animation helpers
// ---------------------------------------------------------------------------

/** Animation type to CSS animation keyframe mapping */
const ANIMATION_CSS_MAP: Record<string, string> = {
  fadeIn: 'opacity: 0; animation: fadeIn {duration}ms {easing} {delay}ms forwards;',
  fadeOut: 'opacity: 1; animation: fadeOut {duration}ms {easing} {delay}ms forwards;',
  slideIn: 'transform: translateY(20px); opacity: 0; animation: slideIn {duration}ms {easing} {delay}ms forwards;',
  scale: 'transform: scale(0.8); opacity: 0; animation: scaleIn {duration}ms {easing} {delay}ms forwards;',
};

/** Generate CSS @keyframes block for animations used in the schema */
function generateKeyframes(nodeList: LowCodeNode[]): string {
  const types = new Set<string>();
  function walk(nodes: LowCodeNode[]) {
    for (const node of nodes) {
      if (node.animation?.type) types.add(node.animation.type);
      if (node.children) walk(node.children);
    }
  }
  walk(nodeList);
  if (types.size === 0) return '';

  const frames: string[] = [];
  if (types.has('fadeIn')) {
    frames.push('  @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }');
  }
  if (types.has('fadeOut')) {
    frames.push('  @keyframes fadeOut { from { opacity: 1; } to { opacity: 0; } }');
  }
  if (types.has('slideIn')) {
    frames.push('  @keyframes slideIn { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }');
  }
  if (types.has('scale')) {
    frames.push('  @keyframes scaleIn { from { transform: scale(0.8); opacity: 0; } to { transform: scale(1); opacity: 1; } }');
  }
  return frames.join('\n');
}

/** Generate inline style object string for an animation config */
function animationToInlineStyle(anim: AnimationConfig): string {
  const duration = anim.duration ?? 300;
  const easing = anim.easing || 'ease';
  const delay = anim.delay ?? 0;
  const animName = anim.type || 'fadeIn';

  const cssMap: Record<string, Record<string, string>> = {
    fadeIn: { opacity: '0' },
    fadeOut: { opacity: '1' },
    slideIn: { transform: 'translateY(20px)', opacity: '0' },
    scale: { transform: 'scale(0.8)', opacity: '0' },
  };

  const initial = cssMap[animName] || {};
  const parts = Object.entries(initial).map(([k, v]) => `${k}: '${v}'`);
  parts.push(`animation: '${animName} ${duration}ms ${easing} ${delay}ms forwards'`);
  return `{ ${parts.join(', ')} }`;
}

/** Generate CSS variable declarations from theme config as a style object string */
function generateThemeCssVars(theme?: LowCodeTheme): string | null {
  if (!theme) return null;
  const vars: Record<string, string> = {};
  if (theme.primaryColor) vars['--primary-color'] = theme.primaryColor;
  if (theme.backgroundColor) vars['--background-color'] = theme.backgroundColor;
  if (theme.fontFamily) vars['--font-family'] = theme.fontFamily;
  if (theme.fontSize) vars['--font-size'] = theme.fontSize;
  if (Object.keys(vars).length === 0) return null;
  return JSON.stringify(vars);
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Indent a block of text by the given number of spaces */
function indent(text: string, spaces: number): string {
  const pad = ' '.repeat(spaces);
  return text
    .split('\n')
    .map((line) => (line.trim() ? pad + line : line))
    .join('\n');
}

/** Collect all unique componentNames used in the schema tree (including slots) */
function collectComponentNames(schema: LowCodeSchema): Set<string> {
  const names = new Set<string>();
  function walk(node: { componentName: string; children?: any[]; slots?: Record<string, any[]> }) {
    names.add(node.componentName);
    if (node.children) {
      for (const child of node.children) walk(child);
    }
    if (node.slots) {
      for (const slotNodes of Object.values(node.slots)) {
        for (const child of slotNodes) walk(child);
      }
    }
  }
  walk(schema);
  return names;
}

/** Sanitize a string to be a valid JS identifier */
function sanitizeId(raw: string): string {
  return raw.replace(/[^a-zA-Z0-9_$]/g, '_');
}

/** Convert a camelCase prop name to a JSX-safe attribute name */
function propToAttrName(prop: string): string {
  // className vs class etc. are handled by Taro automatically
  return prop;
}

/** Escape a string for embedding in JS source */
function escapeString(val: string): string {
  return val.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n');
}

/** i18n 标记正则 */
const I18N_MARK_RE = /\$t\('([^']+)'\)/g;

/** 替换 $t('key') 为 i18n.t('key') */
function resolveI18nMarks(text: string): string {
  return text.replace(I18N_MARK_RE, (_match, key: string) => `i18n.t('${key}')`);
}

/** Resolve a data-binding expression like {{state.title}} to a JS expression */
function resolveExpression(expression: string): string {
  // Replace {{xxx}} patterns with template literal interpolation
  return expression.replace(/\{\{([^}]+)\}\}/g, (_match, expr: string) => {
    const trimmed = expr.trim();
    // api.xxx.data -> apiData[xxx].data
    if (trimmed.startsWith('api.')) {
      const rest = trimmed.slice(4); // e.g. "users.data"
      return `\${apiData.${rest} ?? ''}`;
    }
    if (trimmed.startsWith('dataSource.')) {
      const rest = trimmed.slice(11);
      return `\${apiData.${rest} ?? ''}`;
    }
    if (trimmed.startsWith('ds.')) {
      const rest = trimmed.slice(3);
      return `\${apiData.${rest} ?? ''}`;
    }
    // state.xxx -> state[xxx]
    if (trimmed.startsWith('state.')) {
      return `\${${trimmed}}`;
    }
    // Fallback: treat as a direct JS expression
    return `\${${trimmed}}`;
  });
}

/** Resolve an expression for use as a JSX attribute value.
 *  If the expression is a simple template with no literal parts, return the
 *  inner expression directly (for non-string props). Otherwise wrap in backticks.
 */
function resolveAttrExpression(expression: string, propName: string): string {
  const hasTemplate = /\{\{/.test(expression);
  if (!hasTemplate) {
    // Pure literal
    return JSON.stringify(expression);
  }

  const resolved = resolveExpression(expression);
  const isStringProp = ['text', 'title', 'subTitle', 'description', 'placeholder',
    'label', 'activeText', 'inactiveText', 'navigationBarTitleText'].includes(propName);

  if (isStringProp) {
    return '`' + resolved + '`';
  }

  // For non-string props, try to extract a single expression
  const singleExprMatch = resolved.match(/^\$\{(.+)\}$/);
  if (singleExprMatch) {
    return singleExprMatch[1];
  }

  return '`' + resolved + '`';
}

// ---------------------------------------------------------------------------
// 1. generateImports
// ---------------------------------------------------------------------------

/**
 * Generate import statements for the components used in the schema.
 * Groups imports by source module.
 */
export function generateImports(
  componentNames: Set<string>,
  options: GeneratePageOptions = {},
  hasI18n: boolean = false,
): string {
  const lines: string[] = [];

  // React hooks
  lines.push("import React, { useState, useEffect, useCallback } from 'react';");

  // Taro
  lines.push("import Taro from '@tarojs/taro';");

  // Group component imports by source
  const bySource = new Map<string, Set<string>>();

  for (const name of componentNames) {
    if (name === 'Page') continue; // Page is the root wrapper, not a real component
    const mapping = COMPONENT_IMPORT_MAP[name];
    if (mapping) {
      if (!bySource.has(mapping.source)) {
        bySource.set(mapping.source, new Set());
      }
      bySource.get(mapping.source)!.add(mapping.importName);
    }
  }

  // @tarojs/components
  const taroComps = bySource.get('@tarojs/components');
  if (taroComps) {
    // Always include View for the page wrapper
    taroComps.add('View');
    lines.push(`import { ${[...taroComps].sort().join(', ')} } from '@tarojs/components';`);
  } else {
    lines.push("import { View } from '@tarojs/components';");
  }

  // @nutui/nutui-react-taro
  const nutuiComps = bySource.get('@nutui/nutui-react-taro');
  if (nutuiComps) {
    lines.push(`import { ${[...nutuiComps].sort().join(', ')} } from '@nutui/nutui-react-taro';`);
  }

  // @hospital/api (optional)
  if (options.useHospitalApi) {
    lines.push("import { request } from '@hospital/api';");
  }

  // i18n (optional)
  if (hasI18n) {
    lines.push("import { createI18n, useI18n } from '@tarojs/i18n';");
  }

  lines.push(''); // blank line after imports
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// 2. generateState
// ---------------------------------------------------------------------------

/**
 * Generate useState declarations for page state variables and API data stores.
 * Returns the state declaration block and a map of dataSourceId -> stateVarName.
 */
export function generateState(
  dataSources: ApiDataSource[],
  stateSchema: Record<string, StateVariable> = {},
): { code: string; apiStateNames: Map<string, string> } {
  const lines: string[] = [];
  const apiStateNames = new Map<string, string>();

  // Page-level state variables
  const stateEntries = Object.entries(stateSchema);
  if (stateEntries.length > 0) {
    lines.push('  // --- Page state variables ---');
    for (const [key, def] of stateEntries) {
      const initValue = JSON.stringify(def.defaultValue ?? '');
      lines.push(`  const [${sanitizeId(key)}, set${capitalize(sanitizeId(key))}] = useState(${initValue});`);
    }
    lines.push('');
  }

  // API data source states
  if (dataSources.length > 0) {
    lines.push('  // --- API data stores ---');
    for (const ds of dataSources) {
      const stateName = `${sanitizeId(ds.id)}Data`;
      const loadingName = `${sanitizeId(ds.id)}Loading`;
      apiStateNames.set(ds.id, stateName);
      lines.push(`  const [${stateName}, set${capitalize(stateName)}] = useState<any>(null);`);
      lines.push(`  const [${loadingName}, set${capitalize(loadingName)}] = useState<boolean>(false);`);
    }
    lines.push('');
  }

  return { code: lines.join('\n'), apiStateNames };
}

function capitalize(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

// ---------------------------------------------------------------------------
// 3. generateEffects
// ---------------------------------------------------------------------------

/**
 * Generate useEffect hooks for data fetching from API data sources.
 * Non-manual data sources fire on mount; manual ones provide refetch functions.
 */
export function generateEffects(
  dataSources: ApiDataSource[],
  apiStateNames: Map<string, string>,
  options: GeneratePageOptions = {},
): string {
  if (dataSources.length === 0) return '';

  const lines: string[] = [];

  // Group: auto-fetch on mount vs manual
  const autoSources = dataSources.filter((ds) => !ds.manual);
  const manualSources = dataSources.filter((ds) => ds.manual);

  // Generate individual fetch functions
  lines.push('  // --- Data fetching functions ---');
  for (const ds of dataSources) {
    const fnName = `fetch${capitalize(sanitizeId(ds.id))}`;
    const stateName = apiStateNames.get(ds.id) || `${sanitizeId(ds.id)}Data`;
    const loadingName = `${sanitizeId(ds.id)}Loading`;
    const setterName = `set${capitalize(stateName)}`;
    const loadingSetter = `set${capitalize(loadingName)}`;

    lines.push(`  const ${fnName} = useCallback(async () => {`);
    lines.push(`    ${loadingSetter}(true);`);
    lines.push('    try {');

    if (options.useHospitalApi) {
      lines.push(`      const res = await request({`);
      lines.push(`        method: '${ds.method}',`);
      lines.push(`        url: '${escapeString(ds.url)}',`);
      if (ds.headers && Object.keys(ds.headers).length > 0) {
        lines.push(`        headers: ${JSON.stringify(ds.headers)},`);
      }
      if (ds.params && Object.keys(ds.params).length > 0) {
        lines.push(`        ${ds.method === 'GET' ? 'params' : 'data'}: ${JSON.stringify(ds.params)},`);
      }
      lines.push('      });');
    } else {
      lines.push(`      const res = await Taro.request({`);
      lines.push(`        method: '${ds.method}',`);
      lines.push(`        url: '${escapeString(ds.url)}',`);
      if (ds.headers && Object.keys(ds.headers).length > 0) {
        lines.push(`        header: ${JSON.stringify(ds.headers)},`);
      }
      if (ds.params && Object.keys(ds.params).length > 0) {
        lines.push(`        ${ds.method === 'GET' ? 'data' : 'data'}: ${JSON.stringify(ds.params)},`);
      }
      lines.push('      });');
    }

    // Extract data using dataPath
    if (ds.dataPath) {
      const pathParts = ds.dataPath.split('.');
      let accessor = 'res.data';
      for (const part of pathParts) {
        accessor += `?.${part}`;
      }
      lines.push(`      ${setterName}(${accessor});`);
    } else {
      lines.push(`      ${setterName}(res.data);`);
    }

    lines.push('    } catch (err) {');
    lines.push(`      console.error('[lowcode] Failed to fetch ${ds.id}:', err);`);
    lines.push(`      ${setterName}(null);`);
    lines.push('    } finally {');
    lines.push(`      ${loadingSetter}(false);`);
    lines.push('    }');
    lines.push(`  }, []);`);
    lines.push('');
  }

  // useEffect for auto-fetch sources
  if (autoSources.length > 0) {
    lines.push('  // --- Auto-fetch on mount ---');
    lines.push('  useEffect(() => {');
    for (const ds of autoSources) {
      const fnName = `fetch${capitalize(sanitizeId(ds.id))}`;
      lines.push(`    ${fnName}();`);
    }
    lines.push('  }, []);');
    lines.push('');
  }

  // Polling effects
  const pollingSources = dataSources.filter(
    (ds) => ds.pollingInterval && ds.pollingInterval > 0,
  );
  if (pollingSources.length > 0) {
    lines.push('  // --- Polling ---');
    for (const ds of pollingSources) {
      const fnName = `fetch${capitalize(sanitizeId(ds.id))}`;
      lines.push('  useEffect(() => {');
      lines.push(`    const timer = setInterval(() => {`);
      lines.push(`      ${fnName}();`);
      lines.push(`    }, ${ds.pollingInterval});`);
      lines.push(`    return () => clearInterval(timer);`);
      lines.push(`  }, []);`);
      lines.push('');
    }
  }

  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// 4. generateEventHandlers
// ---------------------------------------------------------------------------

/**
 * Generate event handler functions from the union of all node events.
 * Deduplicates by handler name.
 */
export function generateEventHandlers(
  nodes: LowCodeNode[],
  apiStateNames: Map<string, string>,
): string {
  const lines: string[] = [];
  const generated = new Set<string>();

  function walk(nodeList: LowCodeNode[]) {
    for (const node of nodeList) {
      if (node.events) {
        for (const handler of node.events) {
          const handlerName = buildHandlerName(node, handler);
          if (generated.has(handlerName)) continue;
          generated.add(handlerName);

          lines.push(`  const ${handlerName} = useCallback(() => {`);
          for (const action of handler.actions) {
            lines.push(indent(generateActionCode(action, apiStateNames, node.id), 4));
          }
          lines.push('  }, []);');
          lines.push('');
        }
      }
      if (node.children) walk(node.children);
    }
  }

  walk(nodes);

  return lines.join('\n');
}

/** Build a unique handler function name from node + event */
function buildHandlerName(node: LowCodeNode, handler: EventHandler): string {
  const eventPascal = handler.event
    .replace(/^on/, '')
    .replace(/^./, (c) => c.toUpperCase());
  return `handle${capitalize(sanitizeId(node.id))}${eventPascal}`;
}

/** Generate code for a single EventAction */
function generateActionCode(
  action: { type: string; payload: Record<string, any> },
  apiStateNames: Map<string, string>,
  currentNodeId?: string,
): string {
  switch (action.type) {
    case 'setData': {
      const targetNodeId = action.payload.targetNodeId || currentNodeId;
      const key = action.payload.key;
      const value = action.payload.value;
      if (!targetNodeId || !key) return '// setData: missing targetNodeId or key';
      // setData sets a prop on a target node — in runtime this is handled by the runtime engine.
      // For static codegen, emit a comment + setState if the target maps to a state variable.
      return `// setData: node=${escapeString(targetNodeId)}, ${key}=${JSON.stringify(value)}\nsetNodeProp('${escapeString(targetNodeId)}', '${escapeString(key)}', ${JSON.stringify(value)});`;
    }
    case 'fetchApi': {
      const dsId = action.payload.dataSourceId ?? action.payload.id;
      if (!dsId) return '// fetchApi: missing dataSourceId';
      return `fetch${capitalize(sanitizeId(dsId))}();`;
    }
    case 'navigate': {
      const url = action.payload.url ?? action.payload.path;
      if (!url) return '// navigate: missing url';
      return `Taro.navigateTo({ url: '${escapeString(url)}' });`;
    }
    case 'showToast': {
      const title = action.payload.title ?? action.payload.message ?? '';
      const icon = action.payload.icon ?? 'none';
      return `Taro.showToast({ title: '${escapeString(title)}', icon: '${icon}' });`;
    }
    case 'updateVariable': {
      const key = action.payload.key ?? action.payload.variable;
      const value = action.payload.value;
      if (!key) return '// updateVariable: missing key';
      return `set${capitalize(sanitizeId(key))}(${JSON.stringify(value)});`;
    }
    default:
      return `// unknown action type: ${action.type}`;
  }
}

// ---------------------------------------------------------------------------
// 5. generateJsx
// ---------------------------------------------------------------------------

/**
 * Recursively generate JSX from a LowCodeNode tree.
 * Returns the JSX string for the given node and its children.
 */
export function generateJsx(
  node: LowCodeNode,
  depth: number = 0,
  apiStateNames: Map<string, string> = new Map(),
): string {
  const pad = '  '.repeat(depth);

  // Skip the Page root — it is rendered as a View wrapper in generatePage
  if (node.componentName === 'Page') {
    if (node.children && node.children.length > 0) {
      return node.children
        .map((child) => generateJsx(child, depth, apiStateNames))
        .join('\n');
    }
    return `${pad}<View />`;
  }

  const mapping = COMPONENT_IMPORT_MAP[node.componentName];
  const tagName = mapping ? mapping.importName : node.componentName;

  // Build props string
  let propsStr = buildPropsString(node, apiStateNames);

  // Add animation inline style if configured
  if (node.animation?.type) {
    const animStyle = animationToInlineStyle(node.animation);
    propsStr += ` style={${animStyle}}`;
  }

  // Handle loop rendering
  if (node.loop) {
    return generateLoopJsx(node, depth, apiStateNames);
  }

  // Handle visibility
  const visibleExpr = node.visible
    ? resolveExpression(node.visible)
    : null;

  // Self-closing if no children
  const hasChildren = node.children && node.children.length > 0;

  if (!hasChildren) {
    // Leaf node — check if it has text content in props
    const textContent = extractTextContent(node);
    if (textContent !== null) {
      let jsx = `${pad}<${tagName}${propsStr}>`;
      jsx += textContent;
      jsx += `</${tagName}>`;
      if (visibleExpr) {
        jsx = `${pad}{(${visibleExpr}) && (\n${indent(jsx, 2)}\n${pad})}`;
      }
      return jsx;
    }

    let jsx = `${pad}<${tagName}${propsStr} />`;
    if (visibleExpr) {
      jsx = `${pad}{(${visibleExpr}) && (\n${indent(jsx, 2)}\n${pad})}`;
    }
    return jsx;
  }

  // Container node — support named slots or default children
  let childrenJsx: string;
  if (node.slots && Object.keys(node.slots).length > 0) {
    // Render named slots
    const slotParts: string[] = [];
    for (const [slotName, slotNodes] of Object.entries(node.slots)) {
      if (slotNodes.length > 0) {
        const slotJsx = slotNodes
          .map((child) => generateJsx(child, depth + 2, apiStateNames))
          .join('\n');
        slotParts.push(`${'  '.repeat(depth + 1)}{/* slot: ${slotName} */}\n${slotJsx}`);
      }
    }
    childrenJsx = slotParts.join('\n') || `${'  '.repeat(depth + 1)}`;
  } else {
    childrenJsx = node.children!
      .map((child) => generateJsx(child, depth + 1, apiStateNames))
      .join('\n');
  }

  let jsx = `${pad}<${tagName}${propsStr}>\n${childrenJsx}\n${pad}</${tagName}>`;

  if (visibleExpr) {
    jsx = `${pad}{(${visibleExpr}) && (\n${indent(jsx, 2)}\n${pad})}`;
  }

  return jsx;
}

/** Components that support validation rules */
const FORM_COMPONENT_NAMES = new Set([
  'NutInput',
  'NutTextarea',
  'NutPicker',
  'NutSwitch',
  'NutCheckbox',
  'NutRadio',
  'NutDatePicker',
]);

function isFormComponent(componentName: string): boolean {
  return FORM_COMPONENT_NAMES.has(componentName);
}

/** Format ValidationRules as a JS object literal string for JSX */
function formatValidationRules(rules: ValidationRules): string {
  const entries: string[] = [];
  if (rules.required) entries.push(`required: true`);
  if (rules.minLength != null) entries.push(`minLength: ${rules.minLength}`);
  if (rules.maxLength != null) entries.push(`maxLength: ${rules.maxLength}`);
  if (rules.min != null) entries.push(`min: ${rules.min}`);
  if (rules.max != null) entries.push(`max: ${rules.max}`);
  if (rules.pattern) entries.push(`pattern: '${escapeString(rules.pattern)}'`);
  if (rules.message) entries.push(`message: '${escapeString(rules.message)}'`);
  return `{ ${entries.join(', ')} }`;
}

/** Build the JSX props string for a node */
function buildPropsString(
  node: LowCodeNode,
  apiStateNames: Map<string, string>,
): string {
  const parts: string[] = [];
  const props = node.props || {};

  for (const [key, value] of Object.entries(props)) {
    // Skip internal/visual-only props that don't map to Taro attributes
    if (shouldSkipProp(key, node.componentName)) continue;

    // Check for data binding on this prop
    const bindingExpr = node.dataBinding?.bindings?.[key];
    if (bindingExpr) {
      parts.push(`${propToAttrName(key)}={${resolveAttrExpression(bindingExpr, key)}}`);
      continue;
    }

    // Literal value
    parts.push(formatPropValue(key, value));
  }

  // Add event handlers
  if (node.events) {
    for (const handler of node.events) {
      const handlerName = buildHandlerName(node, handler);
      parts.push(`${handler.event}={${handlerName}}`);
    }
  }

  // Add validateRules for form components
  if (node.validationRules && isFormComponent(node.componentName)) {
    parts.push(`validateRules={${formatValidationRules(node.validationRules)}}`);
  }

  if (parts.length === 0) return '';

  // Multi-line if too many props
  if (parts.length > 3) {
    return '\n    ' + parts.join('\n    ');
  }
  return ' ' + parts.join(' ');
}

/** Determine if a prop should be skipped during code generation */
function shouldSkipProp(propName: string, componentName: string): boolean {
  // NutText 'text' is rendered as children, not a prop
  if (componentName === 'NutText' && propName === 'text') return true;
  // NutButton 'text' is rendered as children
  if (componentName === 'NutButton' && propName === 'text') return true;
  // NutEmpty 'description' is rendered as children
  if (componentName === 'NutEmpty' && propName === 'description') return true;
  // NutCard 'title', 'subTitle', 'description' are rendered as children in the generated layout
  // NutCell 'title', 'description' are rendered as children
  return false;
}

/** Format a prop value for JSX output */
function formatPropValue(key: string, value: any): string {
  if (typeof value === 'boolean') {
    return value ? key : `${key}={false}`;
  }
  if (typeof value === 'number') {
    return `${key}={${value}}`;
  }
  if (typeof value === 'string') {
    // Handle i18n marks: $t('key') -> {i18n.t('key')}
    if (I18N_MARK_RE.test(value)) {
      I18N_MARK_RE.lastIndex = 0; // reset regex state
      return `${key}={${resolveI18nMarks(value)}}`;
    }
    return `${key}="${escapeString(value)}"`;
  }
  if (value === null || value === undefined) {
    return '';
  }
  // Objects / arrays
  return `${key}={${JSON.stringify(value)}}`;
}

/** Extract text content from a leaf node for inline rendering */
function extractTextContent(node: LowCodeNode): string | null {
  const props = node.props || {};

  switch (node.componentName) {
    case 'NutText': {
      const text = props.text || '文本';
      return I18N_MARK_RE.test(text) ? `{${resolveI18nMarks(text)}}` : escapeString(text);
    }
    case 'NutButton': {
      const text = props.text || '按钮';
      return I18N_MARK_RE.test(text) ? `{${resolveI18nMarks(text)}}` : escapeString(text);
    }
    case 'NutEmpty': {
      const desc = props.description || '暂无数据';
      return I18N_MARK_RE.test(desc) ? `{${resolveI18nMarks(desc)}}` : escapeString(desc);
    }
    default:
      return null;
  }
}

/** Generate JSX for a loop-rendered node */
function generateLoopJsx(
  node: LowCodeNode,
  depth: number,
  apiStateNames: Map<string, string>,
): string {
  const pad = '  '.repeat(depth);
  const loop = node.loop!;
  const itemName = loop.itemName || 'item';
  const indexName = loop.indexName || 'index';

  // Resolve the loop data source expression
  const dataExpr = resolveLoopDataExpression(loop.dataSource, apiStateNames);

  const mapping = COMPONENT_IMPORT_MAP[node.componentName];
  const tagName = mapping ? mapping.importName : node.componentName;
  const propsStr = buildPropsString(node, apiStateNames);

  // Build the inner content
  const innerPad = '  '.repeat(depth + 1);
  const hasChildren = node.children && node.children.length > 0;

  let innerContent: string;
  if (hasChildren) {
    const childrenJsx = node.children!
      .map((child) => generateJsx(child, depth + 2, apiStateNames))
      .join('\n');
    innerContent = `${innerPad}  <${tagName}${propsStr}>\n${childrenJsx}\n${innerPad}  </${tagName}>`;
  } else {
    const textContent = extractTextContent(node);
    if (textContent !== null) {
      innerContent = `${innerPad}  <${tagName}${propsStr}>${textContent}</${tagName}>`;
    } else {
      innerContent = `${innerPad}  <${tagName}${propsStr} />`;
    }
  }

  return [
    `${pad}{(${dataExpr} || []).map((${itemName}, ${indexName}) => (`,
    `${innerPad}  <React.Fragment key={${indexName}}>`,
    innerContent,
    `${innerPad}  </React.Fragment>`,
    `${pad}))}`,
  ].join('\n');
}

/** Resolve a loop data source expression to a JS expression */
function resolveLoopDataExpression(
  expression: string,
  apiStateNames: Map<string, string>,
): string {
  // {{api.users.data.list}} -> apiData.users.data.list
  return expression.replace(/\{\{([^}]+)\}\}/g, (_match, expr: string) => {
    const trimmed = expr.trim();
    if (trimmed.startsWith('api.')) {
      return `apiData.${trimmed.slice(4)}`;
    }
    if (trimmed.startsWith('dataSource.')) {
      return `apiData.${trimmed.slice(11)}`;
    }
    if (trimmed.startsWith('ds.')) {
      return `apiData.${trimmed.slice(3)}`;
    }
    if (trimmed.startsWith('state.')) {
      return trimmed;
    }
    return trimmed;
  });
}

// ---------------------------------------------------------------------------
// 6. generatePage (main entry)
// ---------------------------------------------------------------------------

/**
 * Main entry: generate a complete Taro page TSX source string from a
 * LowCodeSchema and its data sources.
 *
 * @param schema - The page schema root (componentName should be 'Page')
 * @param dataSources - Page-level API data sources
 * @param stateSchema - Page-level state variable definitions
 * @param options - Generation options
 * @returns Complete TSX source string
 */
export function generatePage(
  schema: LowCodeSchema,
  dataSources: ApiDataSource[] = [],
  stateSchema: Record<string, StateVariable> = {},
  options: GeneratePageOptions = {},
): string {
  const sections: string[] = [];

  // --- Header ---
  sections.push(
    [
      '// Auto-generated by lowcode codegen',
      '// Do not edit manually — changes will be overwritten on next generation.',
      `// Generated at: ${new Date().toISOString()}`,
      '',
    ].join('\n'),
  );

  // --- Collect components and generate imports ---
  const componentNames = collectComponentNames(schema);
  const hasI18n = !!schema.i18n;
  sections.push(generateImports(componentNames, options, hasI18n));

  // --- Page config (Taro convention) ---
  const pageTitle = schema.props?.navigationBarTitleText || '页面';
  sections.push(
    [
      "definePageConfig({",
      `  navigationBarTitleText: '${escapeString(pageTitle)}',`,
      "});",
      "",
    ].join('\n'),
  );

  // --- i18n messages ---
  if (schema.i18n) {
    sections.push(
      [
        '// --- i18n messages ---',
        `const messages = ${JSON.stringify(schema.i18n.messages, null, 2)};`,
        `const i18n = createI18n({ locale: '${escapeString(schema.i18n.locale)}', messages });`,
        '',
      ].join('\n'),
    );
  }

  // --- Component function start ---
  sections.push('export default function Page() {');

  // --- State ---
  const { code: stateCode, apiStateNames } = generateState(dataSources, stateSchema);
  if (stateCode) {
    sections.push(stateCode);
  }

  // --- Event handlers ---
  const allNodes = flattenNodes(schema.children ?? []);
  const handlerCode = generateEventHandlers(allNodes, apiStateNames);
  if (handlerCode) {
    sections.push(handlerCode);
  }

  // --- Effects ---
  const effectsCode = generateEffects(dataSources, apiStateNames, options);
  if (effectsCode) {
    sections.push(effectsCode);
  }

  // --- Theme CSS variables ---
  const themeVarsJson = generateThemeCssVars(schema.theme);

  // --- Animation keyframes ---
  const allNodesForAnim = flattenNodes(schema.children ?? []);
  const keyframesCode = generateKeyframes(allNodesForAnim);

  // --- JSX ---
  // Build page style: merge options.pageStyle with theme CSS variables
  const mergedStyle: Record<string, any> = { ...(options.pageStyle || {}) };
  if (themeVarsJson) {
    const themeVars = JSON.parse(themeVarsJson);
    Object.assign(mergedStyle, themeVars);
  }
  const pageStyle = Object.keys(mergedStyle).length > 0
    ? ` style={${JSON.stringify(mergedStyle)}}`
    : '';
  const innerJsx = generateJsx(
    { ...schema, componentName: 'Page' } as LowCodeNode,
    2,
    apiStateNames,
  );

  sections.push('  return (');
  sections.push(`    <View className="page"${pageStyle}>`);
  if (keyframesCode) {
    sections.push(`      <style>{\`${keyframesCode.replace(/\n/g, ' ')}\`}</style>`);
  }
  sections.push(innerJsx);
  sections.push('    </View>');
  sections.push('  );');

  sections.push('}');

  return sections.join('\n');
}

/** Flatten all nodes into a single array (for event handler collection), including slots */
function flattenNodes(nodes: LowCodeNode[]): LowCodeNode[] {
  const result: LowCodeNode[] = [];
  function walk(nodeList: LowCodeNode[]) {
    for (const node of nodeList) {
      result.push(node);
      if (node.children) walk(node.children);
      if (node.slots) {
        for (const slotNodes of Object.values(node.slots)) {
          walk(slotNodes);
        }
      }
    }
  }
  walk(nodes);
  return result;
}
